#!/usr/bin/env python3
"""Fill clinic intake HWPX template with patient data.

- Loads /root/patient_intake.json
- Computes:
  * 만 나이 (full-year Korean age) as of visit date and appends to birth date
  * Normalized phone number 3-4-4
- Replaces {{...}} placeholders in all XML files in extracted HWPX
- Removes stale layout-cache elements (<hp:linesegarray> etc.) from modified paragraphs
- Repackages to /root/clinic_intake_ready.hwpx preserving original zip entry order
"""

from __future__ import annotations

import json
import re
import sys
import zipfile
from dataclasses import dataclass
from datetime import date
from pathlib import Path
from typing import Dict, Iterable, List, Tuple

try:
    from lxml import etree  # type: ignore
except Exception as e:
    print("ERROR: lxml is required for this task but is not available:", e, file=sys.stderr)
    sys.exit(2)


TEMPLATE_HWPX = Path("/root/clinic_intake_template.hwpx")
DATA_JSON = Path("/root/patient_intake.json")
WORK_DIR = Path("/tmp/hwpx_work")
EXTRACTED_DIR = WORK_DIR / "template_extracted"
OUTPUT_HWPX = Path("/root/clinic_intake_ready.hwpx")


PLACEHOLDER_RE = re.compile(r"\{\{([^}]+)\}\}")


def parse_ymd(s: str) -> date:
    try:
        y, m, d = s.split("-")
        return date(int(y), int(m), int(d))
    except Exception as e:
        raise ValueError(f"Invalid date format (expected YYYY-MM-DD): {s!r}") from e


def full_year_age_as_of(birth: date, asof: date) -> int:
    # Korean full-year age (만 나이): year difference minus 1 if birthday hasn't occurred yet in that year.
    age = asof.year - birth.year
    if (asof.month, asof.day) < (birth.month, birth.day):
        age -= 1
    return age


def normalize_phone_344(phone: str) -> str:
    digits = re.sub(r"\D+", "", phone or "")
    # Expected mobile format: 11 digits (010xxxxxxxx). If it doesn't match, return best-effort original digits.
    if len(digits) == 11:
        return f"{digits[0:3]}-{digits[3:7]}-{digits[7:11]}"
    if len(digits) == 10:
        # Fall back: 3-3-4
        return f"{digits[0:3]}-{digits[3:6]}-{digits[6:10]}"
    return digits


def load_data() -> Dict[str, str]:
    raw = json.loads(DATA_JSON.read_text(encoding="utf-8"))
    if not isinstance(raw, dict):
        raise ValueError("patient_intake.json must be an object")

    # Convert all values to strings for substitution.
    data: Dict[str, str] = {}
    for k, v in raw.items():
        data[str(k)] = "" if v is None else str(v)

    # Derived fields
    birth_s = data.get("생년월일", "")
    visit_s = data.get("방문일", "")
    if birth_s and visit_s:
        birth_d = parse_ymd(birth_s)
        visit_d = parse_ymd(visit_s)
        age = full_year_age_as_of(birth_d, visit_d)
        data["생년월일"] = f"{birth_s} ({age}세)"

    phone_s = data.get("회신전화", "")
    if phone_s:
        data["회신전화"] = normalize_phone_344(phone_s)

    return data


def iter_xml_files(root: Path) -> Iterable[Path]:
    for p in root.rglob("*.xml"):
        if p.is_file():
            yield p


def find_descendant_text_nodes(elem) -> List[etree._Element]:
    # In HWPML, text nodes are typically <hp:t>. We handle any tag that ends with 't'.
    nodes = []
    for t in elem.iter():
        if not isinstance(t.tag, str):
            continue
        if t.tag.endswith("}t") or t.tag == "t":
            nodes.append(t)
    return nodes


def has_any_placeholder(s: str) -> bool:
    return "{{" in s and "}}" in s


def replace_placeholders_in_text(s: str, mapping: Dict[str, str]) -> Tuple[str, bool]:
    changed = False
    out = s
    for key, val in mapping.items():
        ph = "{{" + key + "}}"
        if ph in out:
            out = out.replace(ph, val)
            changed = True
    return out, changed


def remove_linesegarrays_from_paragraph(p_elem) -> int:
    removed = 0
    # Remove any descendants whose localname is 'linesegarray'
    for child in list(p_elem):
        if not isinstance(child.tag, str):
            continue
        local = etree.QName(child).localname
        if local == "linesegarray":
            p_elem.remove(child)
            removed += 1
    return removed


def process_xml_file(xml_path: Path, mapping: Dict[str, str]) -> bool:
    """Returns True if file was modified."""
    parser = etree.XMLParser(remove_blank_text=False, recover=True, encoding="utf-8")
    tree = etree.parse(str(xml_path), parser)
    root = tree.getroot()

    file_modified = False

    # Iterate paragraphs (<hp:p>) by localname.
    for p in root.iter():
        if not isinstance(p.tag, str):
            continue
        if etree.QName(p).localname != "p":
            continue

        paragraph_modified = False

        t_nodes = find_descendant_text_nodes(p)

        # First pass: do per-node replacement.
        for t in t_nodes:
            txt = t.text or ""
            if not has_any_placeholder(txt):
                continue
            new_txt, changed = replace_placeholders_in_text(txt, mapping)
            if changed:
                t.text = new_txt
                paragraph_modified = True

        # Second pass: if placeholders remain in paragraph text (possibly split across nodes),
        # do a paragraph-level join/replace and consolidate into the first text node.
        if t_nodes:
            joined = "".join((t.text or "") for t in t_nodes)
            if has_any_placeholder(joined):
                new_joined, changed = replace_placeholders_in_text(joined, mapping)
                if changed:
                    t_nodes[0].text = new_joined
                    for extra in t_nodes[1:]:
                        # Keep element but clear text to avoid duplicating content.
                        extra.text = ""
                    paragraph_modified = True

        if paragraph_modified:
            remove_linesegarrays_from_paragraph(p)
            file_modified = True

    if file_modified:
        xml_path.write_bytes(
            etree.tostring(
                tree,
                encoding="UTF-8",
                xml_declaration=True,
                pretty_print=False,
            )
        )

    return file_modified


def verify_no_placeholders(root: Path) -> List[Tuple[Path, List[str]]]:
    remaining: List[Tuple[Path, List[str]]] = []
    for p in iter_xml_files(root):
        txt = p.read_text(encoding="utf-8")
        if "{{" in txt:
            ph = sorted(set(re.findall(r"\{\{[^}]+\}\}", txt)))
            remaining.append((p, ph))
    return remaining


def repack_hwpx(template_hwpx: Path, extracted_dir: Path, output_hwpx: Path) -> None:
    with zipfile.ZipFile(template_hwpx, "r") as zin:
        names = zin.namelist()
        # HWPX doesn't always have 'mimetype', but if it does, keep it first and stored.
        mimetype_first = names[0] == "mimetype"

    if output_hwpx.exists():
        output_hwpx.unlink()

    with zipfile.ZipFile(template_hwpx, "r") as zin, zipfile.ZipFile(
        output_hwpx, "w"
    ) as zout:
        for i, name in enumerate(zin.namelist()):
            src = extracted_dir / name
            if not src.exists():
                # If some entries aren't extracted as files (e.g., directories), read from original.
                data = zin.read(name)
                info = zin.getinfo(name)
                zi = zipfile.ZipInfo(filename=name, date_time=info.date_time)
                zi.external_attr = info.external_attr
                zi.compress_type = zipfile.ZIP_STORED if (name == "mimetype" and i == 0) else zipfile.ZIP_DEFLATED
                zout.writestr(zi, data)
                continue

            # Copy file bytes from extracted dir.
            data = src.read_bytes()
            info = zin.getinfo(name)
            zi = zipfile.ZipInfo(filename=name, date_time=info.date_time)
            zi.external_attr = info.external_attr
            zi.compress_type = zipfile.ZIP_STORED if (name == "mimetype" and i == 0) else zipfile.ZIP_DEFLATED
            zout.writestr(zi, data)


def main() -> int:
    if not TEMPLATE_HWPX.exists():
        print(f"ERROR: missing template: {TEMPLATE_HWPX}", file=sys.stderr)
        return 2
    if not DATA_JSON.exists():
        print(f"ERROR: missing data: {DATA_JSON}", file=sys.stderr)
        return 2
    if not EXTRACTED_DIR.exists():
        print(f"ERROR: missing extracted directory: {EXTRACTED_DIR}", file=sys.stderr)
        return 2

    mapping = load_data()

    modified_files = 0
    for xml_path in iter_xml_files(EXTRACTED_DIR):
        if process_xml_file(xml_path, mapping):
            modified_files += 1

    remaining = verify_no_placeholders(EXTRACTED_DIR)
    if remaining:
        print("ERROR: Unreplaced placeholders remain:", file=sys.stderr)
        for p, ph in remaining:
            print(f"- {p}: {', '.join(ph)}", file=sys.stderr)
        return 3

    repack_hwpx(TEMPLATE_HWPX, EXTRACTED_DIR, OUTPUT_HWPX)

    print(f"OK: modified_xml_files={modified_files} output={OUTPUT_HWPX}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

